//! W3C Webref property data and the lookups built on it: formal value syntax and
//! shorthand-to-longhand relations.
//!
//! `assets/webref-properties.rs` is generated by `tools/css/webref.ts` from the curated
//! `@webref/css` `css.json` snapshot (CSSWG Web Living Standards): every property that
//! publishes a `syntax` becomes one `WebrefPropertySyntax` row. Regenerate with
//! `vp run webref:generate`; `vp run webref:check` fails when the committed snapshot is
//! stale, which is why the asset itself is never hand-edited.
//!
//! This module is the only reader of that table: property names come from the snapshot,
//! and lookups are ASCII case-insensitive because CSS property names are.

use std::collections::BTreeSet;

/// One curated CSS property definition extracted from the CSSWG Web Living
/// Standards by W3C Webref. The generated table is the source of truth for
/// supported property names and their formal value syntax.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) struct WebrefPropertySyntax {
    /// Property name as published by Webref, for example `grid-template-columns`.
    pub name: &'static str,
    /// The property's formal value syntax, with Webref's own notation.
    pub syntax: &'static str,
    /// Longhands the property sets directly; empty when it is not a shorthand, so a
    /// nested shorthand lists the shorthands it expands to.
    pub longhands: &'static [&'static str],
    /// Webref's logical property group, for example `margin` for `margin-block-start`
    /// and `margin-top`; absent for properties no writing mode maps onto another one.
    pub logical_group: Option<&'static str>,
    /// Specification URL the definition was taken from.
    pub href: &'static str,
}

include!("../../assets/webref-properties.rs");

/// Looks up one property in the generated snapshot, ignoring ASCII case.
///
/// `None` means Webref publishes no property with that name, not that the
/// name is invalid CSS; the exception table in `properties` depends on this
/// distinction.
pub(crate) fn webref_property(name: &str) -> Option<&'static WebrefPropertySyntax> {
    WEBREF_PROPERTIES
        .iter()
        .find(|property| property.name.eq_ignore_ascii_case(name))
}

/// Returns the CSSWG Web Living Standard's formal value syntax for a CSS
/// property, when Webref publishes one.
///
/// This intentionally exposes only the grammar text. Consumers use it to
/// audit their own value domains; parsing it is not part of Stillwind's public
/// utility syntax.
#[must_use]
pub fn csswg_formal_syntax(property: &str) -> Option<&'static str> {
    webref_property(property).map(|definition| definition.syntax)
}

/// Whether two CSS properties compete for one declaration slot.
///
/// Two properties interfere when they name the same property, when one is a shorthand
/// whose longhands (transitively) include the other, when both expand to a shared
/// longhand, or when one is the logical counterpart of the other.
///
/// The writing mode decides which physical side a logical property maps to, so a
/// logical property competes with every physical property of its Webref logical group:
/// `margin-block-start` with `margin-top` and `margin-left`, `block-size` with `width`
/// and `height`. Two properties of the same kind never share a slot, because distinct
/// physical sides are distinct slots and the block and inline axes are orthogonal, so
/// `margin-top` and `margin-bottom`, or `block-size` and `inline-size`, stay
/// independent.
///
/// Custom properties interfere only with an equal name, and `all` interferes with every
/// property it resets. A property Webref does not publish expands to itself, so an
/// unpublished or prefixed name still interferes with an equal one.
///
/// This answers cascade competition rather than which declaration wins: a shorthand and
/// a longhand it covers share one slot, because the later of the two wins either way.
#[must_use]
pub fn properties_interfere(left: &str, right: &str) -> bool {
    if left.eq_ignore_ascii_case(right) {
        return true;
    }
    if left.starts_with("--") || right.starts_with("--") {
        return false;
    }
    if left.eq_ignore_ascii_case("all") {
        return !is_universal_exception(right);
    }
    if right.eq_ignore_ascii_case("all") {
        return !is_universal_exception(left);
    }
    let left_family = longhand_family(left);
    let right_family = longhand_family(right);
    left_family
        .iter()
        .any(|longhand| right_family.contains(longhand))
        || crosses_logical_boundary(&left_family, &right_family)
}

/// Whether `all` leaves the property alone; it resets neither custom properties nor these.
fn is_universal_exception(property: &str) -> bool {
    property.eq_ignore_ascii_case("direction") || property.eq_ignore_ascii_case("unicode-bidi")
}

/// Expands one property to every longhand it can set, including itself.
///
/// Names are lowercased because the generated table publishes them that way. A cycle
/// would stop at the already-collected name rather than loop; Webref publishes none.
fn longhand_family(property: &str) -> BTreeSet<String> {
    let mut family = BTreeSet::new();
    let mut pending = vec![property.to_ascii_lowercase()];
    while let Some(name) = pending.pop() {
        if !family.insert(name.clone()) {
            continue;
        }
        for longhand in webref_property(&name).map_or(&[][..], |definition| definition.longhands) {
            if !family.contains(*longhand) {
                pending.push((*longhand).to_owned());
            }
        }
    }
    family
}

/// Whether the two families meet across the logical/physical boundary of one Webref group.
fn crosses_logical_boundary(left: &BTreeSet<String>, right: &BTreeSet<String>) -> bool {
    left.iter().any(|left_name| {
        let Some(group) = logical_group(left_name) else {
            return false;
        };
        right.iter().any(|right_name| {
            logical_group(right_name) == Some(group)
                && is_logical(left_name) != is_logical(right_name)
        })
    })
}

/// The Webref logical group of one property name, when it publishes one.
fn logical_group(property: &str) -> Option<&'static str> {
    webref_property(property).and_then(|definition| definition.logical_group)
}

/// Whether a property name targets a logical side rather than a physical one.
///
/// Only names inside one logical group are classified, so the check is limited to the
/// axis keywords Webref uses there: a group member naming `block`, `inline`, `start` or
/// `end` is logical, and every other member is physical.
fn is_logical(property: &str) -> bool {
    property
        .split('-')
        .any(|segment| matches!(segment, "block" | "inline" | "start" | "end"))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn generated_webref_snapshot_covers_every_internal_complex_value_domain() {
        for property in [
            "animation",
            "columns",
            "contain",
            "cursor",
            "flex",
            "font-feature-settings",
            "font-stretch",
            "grid-auto-columns",
            "grid-column",
            "grid-template-columns",
            "list-style-image",
            "list-style-type",
            "tab-size",
            "transition-property",
            "vertical-align",
            "will-change",
            "zoom",
        ] {
            let definition = webref_property(property)
                .unwrap_or_else(|| panic!("Webref must define `{property}`"));
            assert!(!definition.syntax.is_empty(), "{property}");
            assert!(definition.href.starts_with("https://"), "{property}");
        }
    }

    #[test]
    fn shorthands_interfere_with_the_longhands_they_cover() {
        assert!(properties_interfere("margin", "margin-top"));
        assert!(properties_interfere("margin-top", "margin"));
        assert!(properties_interfere("margin", "margin"));
        assert!(properties_interfere("Margin", "MARGIN-TOP"));
        // A border expands through border-width to the physical widths.
        assert!(properties_interfere("border", "border-top-width"));
        assert!(properties_interfere("font", "line-height"));
        assert!(!properties_interfere("margin", "padding"));
        assert!(!properties_interfere("margin-top", "margin-left"));
        assert!(!properties_interfere("width", "height"));
    }

    #[test]
    fn custom_properties_and_all_follow_their_own_rules() {
        assert!(properties_interfere("--brand", "--brand"));
        assert!(!properties_interfere("--brand", "--other"));
        assert!(!properties_interfere("--brand", "color"));
        assert!(properties_interfere("all", "color"));
        assert!(properties_interfere("margin", "all"));
        // all resets neither custom properties nor these two.
        assert!(!properties_interfere("all", "--brand"));
        assert!(!properties_interfere("all", "direction"));
        assert!(!properties_interfere("unicode-bidi", "all"));
    }

    #[test]
    fn logical_and_physical_members_of_one_group_interfere() {
        assert!(properties_interfere("margin-top", "margin-block-start"));
        assert!(properties_interfere("margin-block-start", "margin-left"));
        assert!(properties_interfere("margin", "margin-block"));
        assert!(properties_interfere("padding", "padding-inline-start"));
        assert!(properties_interfere("inset", "inset-block-start"));
        assert!(properties_interfere("width", "block-size"));
        assert!(properties_interfere("height", "inline-size"));
        assert!(properties_interfere("min-width", "min-inline-size"));
        assert!(properties_interfere(
            "border-top-width",
            "border-block-start-width"
        ));
        assert!(properties_interfere("overflow-x", "overflow-block"));
        assert!(properties_interfere(
            "border-top-left-radius",
            "border-start-start-radius"
        ));
        // Distinct slots of one group stay independent.
        assert!(!properties_interfere("margin-top", "margin-bottom"));
        assert!(!properties_interfere(
            "margin-block-start",
            "margin-inline-start"
        ));
        assert!(!properties_interfere("width", "height"));
        assert!(!properties_interfere("block-size", "inline-size"));
        assert!(!properties_interfere(
            "border-top-width",
            "border-left-width"
        ));
    }

    #[test]
    fn property_lookup_is_case_insensitive_and_rejects_unknown_names() {
        assert_eq!(webref_property("COLOR"), webref_property("color"));
        assert!(csswg_formal_syntax("color").unwrap().contains("color"));
        assert_eq!(csswg_formal_syntax("not-a-real-property"), None);
    }
}
